contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        require(caller == address(this));

        uint256 balBefore = address(c).balance;

        bool firstReverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool secondReverted;
        c.sudicideAnyone(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint256 balAfter = address(c).balance;

        assert(firstReverted || (!secondReverted && balAfter <= balBefore));
    }

    receive() external payable {}
}

