pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(address caller) internal {
        caller = address(this);
        uint256 balBefore = address(c).balance;
        bool firstReverted;
        try c.sudicideAnyone() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        try c.sudicideAnyone() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 balAfter = address(c).balance;
        assertTrue(firstReverted || (!secondReverted && balAfter <= balBefore));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
